// Counter from 0 to 999 with period 1000, one-hot encoded as a 10-bit
// register. The register is updated on the positive edge of the clock.
module TopModule(input clk, input reset, output reg [9:0] q);
  always @(posedge clk) begin
    if (reset) q <= 10'b0000000001;
    else q <= (q == 10'b1000000000) ? 10'b0000000001 : q + 1;
  end
endmodule

